 V _selectedRecord=V.Map();string _importPath="",_exportPath="";
 void RecordsPage(){var journal=Card(_body,"城市声音","低频城市消息反映实际建设、贸易和趋势。紧急问题仍由可定位警报提示。",Blue);var chirps=_feedback.history();if(chirps.Count==0)Label(journal,"本视口尚未记录城市声音；不补造旧消息。",17,Muted);foreach(var item in chirps.Reverse()){var source=item;Label(journal,item["text"].Text,18);if(item.Get("building_id","").Text!=""&&S["projects"].Has(item["building_id"])){Button(journal,"定位来源 ›",()=>{CloseArchive();SelectBuilding(source["building_id"].Text);SetLayer(source["layer"].Text);});}Fold(journal,"变化依据",c=>Raw(c,item["evidence"]));}
  var alerts=Card(_body,"当前实际警报","警报按原因合并，使用进入 / 退出阈值与本地持续时间。",Gold);var list=_feedbackView.Get("alerts",V.Arr());if(list.Count==0)Label(alerts,"当前没有已确认的硬警报。",18,Green);foreach(var item in list){var alert=item;Label(alerts,G.project_name(alert["building_id"].Text)+" · "+alert["text"].Text,19,alert["severity"].Long==2?Red:Gold);Button(alerts,"定位问题来源",()=>{CloseArchive();SelectBuilding(alert["building_id"].Text);SetLayer(alert["layer"].Text);});Fold(alerts,"实际依据与满足率",c=>Raw(c,alert["evidence"]));}
  var records=Card(_body,"已保存的城市","结束后留存的只读城市记录。查看不会载入或改变当前经营。",Green);var archives=Block.list_archives(G);if(archives.Count==0)Label(records,"尚无城市结算记录。",18,Muted);foreach(var record in archives){var item=record;var row=Row(records,"Archived City",62);Label(row,record.Get("name","城市").Text,23,Gold);Label(row,F(record.Get("population",0).Double)+" 人 · "+Clock.duration(G,record.Get("local_elapsed_seconds",0).Double),17,Muted);Button(row,"查看只读记录",()=>{_selectedRecord=item.Duplicate(true);Navigate("record");});}
  var log=Card(_body,"本城事件与操作记录","从实际保存日志读取，保留事件时间和来源。",Blue);foreach(var item in S["log"].Reverse().Take(160)){Label(log,F(item.Get("h",0).Double,2)+" 来生月 · "+item.Get("text",item.Get("kind","城市记录")).Text,17);Fold(log,"事件来源",c=>Raw(c,item));}
  Fold(_body,"历史城市成果记录",c=>{foreach(var row in Civic.task_rows(G)){Label(c,row["name"].Text+" · "+row["status"].Text,18);Label(c,row["reading"].Text,15,Muted);}Raw(c,S.Get("city_goal",V.Map()));});
 }
 void RecordPage(){var record=_selectedRecord;if(record.Count==0){Label(_body,"未选择城市记录。",22);return;}var intro=Card(_body,record.Get("name","城市").Text,"只读记录 / 不会继续模拟或覆盖当前城",Gold);Metric(intro,"本局人口",F(record.Get("population",0).Double)+" 人");Metric(intro,"本局通货",F(record.Get("currency",0).Double));Metric(intro,"已用 DT",F(record.Get("dt_spent",0).Double,2));Metric(intro,"来生时长",Clock.duration(G,record.Get("local_elapsed_seconds",0).Double));Metric(intro,"实际在线时长",F(record.Get("active_real_seconds",0).Double/3600,2)+" 现实小时");var theme=record.Get("theme",V.Map());Label(intro,Themes._definition(G,theme.Get("id","").Text).Get("name","未选择主题").Text+" · "+(theme.Get("completed",false).Bool?"主题完成":"主题未完成"),20,Green);
  var rewards=Card(_body,"奖励与构筑快照","保留当时的候选与领取状态。",Blue);foreach(var item in record.Get("rewards",V.Arr()))Label(rewards,item.Get("source","成长奖励").Text+" · "+(item.Get("claimed",false).Bool?"已领取 "+G.c.bonuses.Get(item.Get("chosen_bonus",""),V.Map()).Get("name",item.Get("chosen_bonus","")).Text:"未领取 · 候选保留"),17);var capstone=record.Get("capstone",V.Map());if(capstone.Count!=0){var card=Card(_body,capstone.Get("name","主题地标").Text,"当时已正式挂牌",Gold);Fold(card,"地标完整规则",c=>Raw(c,capstone));}
  var history=Card(_body,"城史","按记录保存的真实事件顺序。",Blue);foreach(var entry in record.Get("history",V.Arr()))Label(history,F(entry.Get("h",0).Double,2)+" 来生月 · "+entry.Get("text",entry.Get("kind","城市事件")).Text,17);Fold(_body,"原始只读记录与完整城市快照",c=>Raw(c,record));
 }
 void SourcesPage(){var identity=Card(_body,"来源与规则档案","完整规则、场、运营商和结算记录按主体展开；不把原始 JSON 当成城市总览。",Blue);Label(identity,"当前来源：最近周期实际 / simulation tick "+S["simulation_tick"].Long,18,Green);foreach(var operatorValue in Rules.ids(G.c.operators)){var orgId=operatorValue.Text;var op=G.c.operators[orgId];var box=Card(_body,"运营商 / "+op["name"].Text,op.Get("summary","").Text,Gold);Label(box,"槽轨 "+string.Join(" → ",op.Get("slot_track",V.Arr()).Select(x=>Catalog.SLOT_NAMES.Get(x,x).Text)),18,Blue);var buildings=S["projects"].Values.Where(x=>x.Get("operator_org","").Text==orgId&&!x.Get("special",false).Bool).ToArray();Metric(box,"本区运营建筑",buildings.Length+" 座");foreach(var project in buildings){var id=project["id"].Text;Button(box,G.project_name(id)+" · 建筑来源 ›",()=>Navigate("building",id));}Fold(box,"组织、投标偏好与完整定义",c=>{Raw(c,op);Raw(c,S["organizations"].Get(orgId,V.Map()));});}
  Fold(_body,"当前场与逐地格贡献",c=>{Raw(c,S["fields"]);Raw(c,S["authored_fields"]);foreach(var tile in Rules.ids(S["cells"])){var fields=S["cells"][tile].Get("fields",V.Map());if(fields.Count==0)continue;Label(c,"地块 "+tile.Text+" · "+G.c.tags_text(S["cells"][tile]["traits"]),18,Blue);Raw(c,fields);}});
  Fold(_body,"服务池与真实分配",c=>{Raw(c,S["metrics"].Get("service_pools",V.Map()));Raw(c,S["metrics"].Get("service_links",V.Arr()));Raw(c,S["metrics"].Get("employment_links",V.Arr()));});
  Fold(_body,"资源守恒与真实结算审计",c=>Raw(c,S["audit"]));
  Fold(_body,"全部建筑定义与成长树",c=>{foreach(var id in Rules.ids(G.c.projects)){var def=G.c.projects[id];Label(c,def.Get("name",id).Text+" · T"+def.Get("tier",1).Long,19,Gold);Raw(c,def);}});
  Fold(_body,"编译后的规则、条件与来源追踪",c=>Raw(c,G.compiled));
 }
 void SettingsPage(){var display=Card(_body,"显示与输入","桌面全屏 1920×1080；界面缩放、地图镜头缩放和字号互相独立。",Blue);var scales=Row(display);foreach(var value in new[]{.8,1.0,1.2}){var v=value;Button(scales,(Math.Abs(Runtime.DisplaySettings["ui_scale"].Double-v)<.01?"✓ ":"")+"界面 "+(int)(v*100)+"%",()=>{Runtime.SetDisplaySetting("ui_scale",v);ApplyDisplay();RenderPage();});}var text=Row(display);foreach(var value in new[]{1.0,1.25,1.5}){var v=value;Button(text,"字号 "+(int)(v*100)+"%",()=>{Runtime.SetDisplaySetting("text_scale",v);RenderPage();RebuildAmbient();});}
  foreach(var entry in new[]{new[]{"citizen_bubbles","市民气氛泡泡"},new[]{"reduced_motion","减少动态"},new[]{"high_contrast","高对比度"},new[]{"all_links","完整关系线"}}){var id=entry[0];Button(display,entry[1]+"："+(Runtime.DisplaySettings.Get(id,false).Bool?"开":"关"),()=>{Runtime.SetDisplaySetting(id,!Runtime.DisplaySettings.Get(id,false).Bool);ApplyDisplay();RenderPage();});}Button(display,"声音："+(S["settings"].Get("sound",true).Bool?"开":"关"),()=>Command(g=>{g.s["settings"]["sound"]=!g.s["settings"].Get("sound",true).Bool;return "";}));var fps=Row(display);foreach(var rate in new[]{0,30,60,120}){var r=rate;Button(fps,r==0?"自动 · 60 FPS":r+" FPS",()=>{Runtime.SetDisplaySetting("frame_limit",r);ApplyDisplay();RenderPage();});}Label(display,"鼠标点击选择地格；滚轮独立缩放地图；L / Shift+L 循环图层；P 暂停；Esc 逐级返回。输入框和档案持有键盘时不切换地图。",16,Muted,65);
  var save=Card(_body,"存档与城市备份","Unity 使用独立保存格式和目录，保留主存档与上一份有效备份。",Green);var controls=Row(save);Button(controls,"保存当前城市",()=>Runtime.Save(),true);Button(controls,"载入当前存档",()=>{if(Runtime.Load()==""){_feedback.reset();CloseArchive();}});Label(save,"保存位置："+Runtime.SavePath,15,Muted,55);if(_exportPath=="")_exportPath=Path.Combine(Runtime.StorageRoot,"exports","MET-Unity-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json");var export=InputBox(save,_exportPath,"输入导出路径");export.onValueChanged.AddListener(v=>_exportPath=v);Button(save,"导出城市备份",()=>Runtime.Export(_exportPath));var import=InputBox(save,_importPath,"输入 Unity 城市备份完整路径");import.onValueChanged.AddListener(v=>_importPath=v);Button(save,"载入此城市备份",()=>{if(string.IsNullOrWhiteSpace(_importPath)){ShowMessage("请输入备份文件完整路径。");return;}if(Runtime.Load(_importPath)==""){_feedback.reset();CloseArchive();}});
  var city=Card(_body,"时间与生命周期","后台和关闭只记录离开时长，不补算资源、移民、事件、DT或奖励。",Gold);var summary=Clock.summary(G);Metric(city,"真实活跃在线",F(summary["active_real_seconds"].Double/3600,2)+" 小时");Metric(city,"记录的离开时长",F(summary["offline_recorded_seconds"].Double/3600,2)+" 小时");Metric(city,"当前暂停原因",summary.Get("pause_reason","").Text);Button(city,"查看年度 / 尾声",()=>Navigate("settlement"));Button(city,"开始一座独立新城…",()=>Confirm("重新开始独立新城？","当前存档将写入上一份有效备份，新城不继承资源、卡、蓝图和地标。DT已经耗尽的城可先在尾声保存只读结算记录。",()=>{Runtime.NewCity(DateTime.UtcNow.Ticks%2147483000);_feedback.reset();SelectedTile="";SelectedBuilding="";OpenArchive("start");}));Button(city,"保存并退出",()=>{Runtime.Save();Application.Quit();});
 }
 void RebuildAmbient(){foreach(var pair in _fontBases.ToArray()){if(pair.Key==null){_fontBases.Remove(pair.Key);continue;}pair.Key.fontSize=Mathf.RoundToInt(pair.Value*TextScale);}RefreshContext();UpdateHud();RenderStatus();}

}
